const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: 'x²' },
      { kind: 'text', payload: '− 7' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '+ 3' },
      { kind: 'text', payload: '= 0' },
      { kind: 'text', payload: 'a = 2' },
      { kind: 'text', payload: 'b = −7' },
      { kind: 'text', payload: 'c = 3' },
      { kind: 'text', payload: 'x =' },
      { kind: 'text', payload: '−b ± √(b² − 4ac)' },
      { kind: 'text', payload: '2a' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 25' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W / 2;
    var yEq = H * 0.16;
    var yCoeff = H * 0.31;
    var xA = cx - 140;
    var xB = cx - 55;
    var xC = cx + 25;
    var xEq = cx + 95;
    var xX2 = cx - 112;
    var xX = cx - 24;
    var black = '#26354a';
    var blue = '#1F6FEB';
    var red = '#D9480F';
    var green = '#2F9E44';
    var purple = '#7048E8';

    var leaderA = visualSdk.polyline([[xA, yEq + 22], [xA, yCoeff - 8]]);
    var leaderB = visualSdk.polyline([[xB, yEq + 22], [xB, yCoeff - 8]]);
    var leaderC = visualSdk.polyline([[xC, yEq + 22], [xC, yCoeff - 8]]);

    var yNum = H * 0.47;
    var yFrac = H * 0.545;
    var yDen = H * 0.62;
    var numCenterX = cx + 30;
    var barX1 = cx - 110;
    var barX2 = cx + 170;
    var fracBar = visualSdk.polyline([[barX1, yFrac], [barX2, yFrac]]);
    var xLabelX = cx - 135;
    var yDisc = H * 0.80;

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-root-formula',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'leader-a', commands: leaderA },
        { id: 'leader-b', commands: leaderB },
        { id: 'leader-c', commands: leaderC },
        { id: 'frac-bar', commands: fracBar }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'leader-a', fill: blue, stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'leader-b', fill: red, stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'leader-c', fill: green, stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'frac-bar', fill: black, stroke: { width: 2, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: xA, y: yEq }, hAlign: 'center', vAlign: 'middle', color: blue },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: xX2, y: yEq }, hAlign: 'center', vAlign: 'middle', color: black },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: xB, y: yEq }, hAlign: 'center', vAlign: 'middle', color: red },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: xX, y: yEq }, hAlign: 'center', vAlign: 'middle', color: black },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: xC, y: yEq }, hAlign: 'center', vAlign: 'middle', color: green },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: xEq, y: yEq }, hAlign: 'center', vAlign: 'middle', color: black },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: xA, y: yCoeff }, hAlign: 'center', vAlign: 'top', color: blue },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: xB, y: yCoeff }, hAlign: 'center', vAlign: 'top', color: red },
          { type: 'label', contentId: metrics[8].contentId, anchor: { x: xC, y: yCoeff }, hAlign: 'center', vAlign: 'top', color: green },
          { type: 'label', contentId: metrics[9].contentId, anchor: { x: xLabelX, y: (yNum + yDen) / 2 }, hAlign: 'right', vAlign: 'middle', color: black },
          { type: 'label', contentId: metrics[10].contentId, anchor: { x: numCenterX, y: yNum }, hAlign: 'center', vAlign: 'middle', color: black },
          { type: 'label', contentId: metrics[11].contentId, anchor: { x: numCenterX, y: yDen }, hAlign: 'center', vAlign: 'middle', color: black },
          { type: 'label', contentId: metrics[12].contentId, anchor: { x: cx, y: yDisc }, hAlign: 'center', vAlign: 'top', color: purple }
        ]
      }
    };
  }
};
